"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1578],{6511:function(e){e.exports=JSON.parse('{"blogPosts":[{"id":"launch","metadata":{"permalink":"/ezbackend/blog/launch","editUrl":"https://github.com/facebook/docusaurus/edit/master/website/blog/blog/2021-09-30-launch.md","source":"@site/blog/2021-09-30-launch.md","title":"We\'re Ready to Use!","description":"Welcome to EzBackend. My name is Philip Wee. My co-founder Stephen and I built this package because we felt that backend setup takes too long. We made ezbackend to solve this problem, and the idea behind it is that devs like you and me should focus on what\'s important, like planning the data models and relations (which is all you should have to put in effort for when you use our package)","date":"2021-09-30T00:00:00.000Z","formattedDate":"September 30, 2021","tags":[],"readingTime":0.595,"truncated":false,"authors":[{"name":"Philip Wee","title":"EzBackend","url":"https://github.com/PhilipWee?tab=repositories","imageURL":"https://media-exp1.licdn.com/dms/image/C5603AQFFKqMaY0AuIw/profile-displayphoto-shrink_400_400/0/1553178335843?e=1638403200&v=beta&t=rNiF6XA4e4eF1GRIR7uTDHiEUI2XTRFdoioNktgcAQ4"}]},"content":"Welcome to EzBackend. My name is Philip Wee. My co-founder Stephen and I built this package because we felt that backend setup takes too long. We made ezbackend to solve this problem, and the idea behind it is that devs like you and me should focus on what\'s important, like planning the data models and relations (which is all you should have to put in effort for when you use our package)\\n\\nOur mission for you developers is to make backend setup as easy as possible, and we believe that every function should take up more than 1 line of code. We really hope you enjoy using this package!\\n\\nYou can join our discord community here ------\x3e <span style={{color:\'#5396CE\'}}>https://discord.gg/RwgdruFJHc</span>"}]}')}}]);